import{_ as i,l as n,o as e,c as t,v as o,p as s,x as r,d,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"Colossal-AI","description":"","frontmatter":{"title":"Colossal-AI","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/colossal-ai.md","filePath":"llm/colossal-ai.md","lastUpdated":1789023840000}'),c={name:"llm/colossal-ai.md"};function h(P,a,D,u,A,g){const l=n("Mermaid");return e(),t("div",null,[a[1]||(a[1]=o('<h1 id="colossal-ai" tabindex="-1">Colossal-AI <a class="header-anchor" href="#colossal-ai" aria-label="Permalink to &quot;Colossal-AI&quot;">​</a></h1><div class="epigraph"><p>把 1D 张量并行当成默认不够：在不同机器拓扑上，2D / 2.5D / 3D 切矩阵可以换通信体积；异构显存再交给 Gemini，而不是只提供另一套 ZeRO 配置文件。</p><footer>—— Bian et al., Colossal-AI: A Unified Deep Learning System For Large-Scale Parallel Training, arXiv:2110.14883</footer></div><p>HPC-AI Tech 的 <strong>Colossal-AI</strong>（开源仓库 <code>hpcaitech/ColossalAI</code>）把自己定位成统一的大规模并行训练系统：多维张量并行、流水线、序列并行、数据并行，以及异构内存管理 <strong>Gemini</strong>（思路来自 PatrickStar，arXiv:2108.05818）。2021 年系统论文 2110.14883 是读它的起点；后来的 Booster 插件、ShardFormer、Gemini 动态卸载是同一条产品线上的接口演化。本篇写系统主张与论文里的切分家族，并标明：<strong>当前主线文档已写明 2D/2.5D 等旧模块不再直接支持、计划并入 ShardFormer</strong>——不要把 2021 论文的 API 当成 2026 年 <code>pip install</code> 的默认路径。不编造未写入论文或文档的「一张卡训 GPT-3」营销数；对比 DeepSpeed-Chat 的 15× 是对方论文的对照，不是 Colossal 自己的主结果。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Megatron 式 1D <a href="/llm/tensor-parallel">张量并行</a> 对 NVLink 友好，但激活仍常按完整序列驻留，通信是每层 All-Reduce。机器若是弱于 DGX 的以太网网格，或卡数刚好是平方/立方，1D 不一定是通信最优。学术界已有基于 SUMMA / Cannon 的 2D 切法、基于 2.5D 矩阵乘的深度维、以及 3D 立方切分：它们同时切输入、权重与输出，内存与通信公式随处理器网格变。需要一个系统把这些切法收成可切换的层实现，而不是让用户自己改集合通信。</p><p>第二问是少卡大模型。ZeRO-Offload 常把优化器与梯度<strong>静态</strong>划到 CPU：GPU 侧预算写死，一旦非模型显存（激活、碎片）涨一截就 OOM，即使主机 DRAM 仍空。Gemini 要动态地在 CPU–GPU 之间搬模型张量，用迭代的周期性先采样再调度。</p><h3 id="多维张量切分是系统卖点" tabindex="-1">多维张量切分是系统卖点 <a class="header-anchor" href="#多维张量切分是系统卖点" aria-label="Permalink to &quot;多维张量切分是系统卖点&quot;">​</a></h3><p>论文把 1D 之外的选项写成：</p><ul><li><strong>2D</strong>（Xu 等）：\\(N\\) 张卡排成方阵，形状 \\([P,Q]\\) 的张量切成 \\([P/\\sqrt{N},\\,Q/\\sqrt{N}]\\) 的块，矩阵乘走 SUMMA/Cannon。激活与权重都切，内存更匀；通信模式与 1D All-Reduce 不同。</li><li><strong>2.5D</strong>（Wang 等）：\\(N=S^2\\cdot D\\)，多一个 depth。\\(D=1\\) 退化近 2D；\\(D\\gt 1\\) 用更多卡换通信。文档曾给出基于 ring 的带宽/延迟阶。</li><li><strong>3D</strong>（Bian 等）：立方切分；并非每个张量都有三维，实现上常对第一维切两次。</li></ul><p>选择哪一档，应对齐机器拓扑：方阵网卡走 2D，有额外深度维再开 2.5D。流水线与数据并行仍可叠。序列并行另切激活的序列维。这是 2021 系统相对「只提供 Megatron 1D + ZeRO」的差异化。</p><p><span class="marginnote">最新 Colossal-AI 文档写明 2D/2.5D <strong>当前版本不直接支持</strong>，将并入 ShardFormer；旧用户看 ColossalAI-Examples。写实验记录时应写版本与插件名（<code>GeminiPlugin</code> 等），不要只写「开了 2.5D」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>今日推荐入口是 <strong>Booster + Plugin</strong>，而不是 2021 论文里的 <code>colossalai.nn.layer.parallel_2p5d</code> 直接 import。</p><p><code>GeminiPlugin</code>：ZeRO-3 语义加 chunk 与异构内存。适合「十亿到百亿、跨节点带宽尚可、千卡以下」一类文档描述的场景；文档也写明不支持本地梯度累积。<code>ShardFormer</code>：按配置把 Hugging Face 式模型改写成切分实现，承接未来的多维 TP。流水线、序列并行、混合精度作为正交开关。PatrickStar / Gemini 的两阶段：warmup 若干 step 用 MemStatsCollector 采样非模型显存；之后 StatefulTensorMgr 按采样结果搬张量，目标是减少 CPU–GPU 流量，而不是每步贪心。</p><p>相对 ZeRO-Offload 的静态划分，Gemini 的图景是：GPU 预算随激活波动时，把一部分模型块换出到 CPU（文档还提到 NVMe 作为存储层级的组成），避免「GPU 差一口气、主机闲着却崩」。代价是预热步的统计若不准，稳态会过度搬运。</p>',15)),(e(),s(m,null,{default:r(()=>[p(l,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%8D%95%E8%AE%BE%E5%A4%87%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20B%5B%22Booster%20%2B%20Plugin%22%5D%0A%20%20B%20--%3E%20G%5B%22Gemini%3A%20%E5%8A%A8%E6%80%81%20CPU%2FGPU%22%5D%0A%20%20B%20--%3E%20S%5B%22ShardFormer%3A%20%E5%88%87%E5%88%86%E5%B1%82%22%5D%0A%20%20B%20--%3E%20PP%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%20%2F%20%E5%BA%8F%E5%88%97%E5%B9%B6%E8%A1%8C%22%5D%0A%20%20G%20--%3E%20W%5B%22warmup%20%E9%87%87%E6%A0%B7%20MSC%22%5D%0A%20%20W%20--%3E%20STM%5B%22STM%20%E6%90%AC%20StatefulTensor%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h3 id="gemini-与-zero-offload-的差别" tabindex="-1">Gemini 与 ZeRO-Offload 的差别 <a class="header-anchor" href="#gemini-与-zero-offload-的差别" aria-label="Permalink to &quot;Gemini 与 ZeRO-Offload 的差别&quot;">​</a></h3><p>Offload 把「哪些状态在 CPU」写成配置常数。Gemini 把张量标成有状态对象，按迭代相位决定驻留。warmup 必须发生在真实 batch 与激活检查点开关已经定下来之后；改序列长度却不重做采样，调度会按过期直方图搬错。chunk 粒度决定 All-Gather 次数与碎片：太大则峰值高，太小则启动税高——与 FSDP wrap unit 是同一旋钮，名字不同。</p><p><span class="marginnote">Gemini 不是新的并行维。数据仍按 batch 切，参数仍按 ZeRO 下标切。它不替代 2D TP 去加速单层 GEMM，只是让少卡在异构内存上活下来。宽矩阵仍要 TP 或近端带宽。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>2D/2.5D/3D 的正确性来自分布式矩阵乘：部分积在网格上广播或平移，数学上恢复 \\(Y=XW\\)。实现错误通常表现为某条网格维上少一次 reduce，logits 只有分片词表能学。1D Megatron 用一对 \\(f,g\\) 就能讲完；2D 必须讲清 SUMMA 的面板广播顺序，调试更难。这是后来主线收缩到 Gemini + ShardFormer、把高维 TP 降为「将并入」的工程原因之一：维护成本高于 1D+ZeRO 对大多数用户的收益。</p><p>Gemini 的机制是把非模型显存当成外生扰动：激活检查点一开，GPU 空出一截，STM 可以把更多参数拉回；flash attention 一开，空出的可能是另一截。所以「Gemini 比 Offload 更能塞大模型」是条件句，取决于采样是否覆盖你的真实核。</p><h3 id="booster-shardformer-之后怎么读旧论文" tabindex="-1">Booster / ShardFormer 之后怎么读旧论文 <a class="header-anchor" href="#booster-shardformer-之后怎么读旧论文" aria-label="Permalink to &quot;Booster / ShardFormer 之后怎么读旧论文&quot;">​</a></h3><p>2110.14883 仍是引用多维 TP 公式的正确出处。复现 2.5D 应回到当时示例仓库或论文算法，而不是假设 <code>GeminiPlugin()</code> 已经打开 2.5D。EnergonAI 等推理侧项目、以及后续博客里的具体模型配方，要以对应文档为准，不要全部算进 2021 系统论文。DeepSpeed-Chat 文中相对 Colossal 的倍数，用的是对方选定的 RLHF 基线，不能反过来说 Colossal 预训练一定慢 15×。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在没有方阵进程网格的作业上强开 2D。不要把「异构训练」理解成 Infinity 的 NVMe 流水已经默认打开——Gemini 文档以 CPU–GPU 为主，NVMe 是否启用看版本。检查点与插件、chunk、TP 度绑定。数值上，ZeRO 聚集顺序与 CPU Adam 不保证与纯 GPU Adam 比特一致。</p><p>Colossal-AI 与 Megatron-Core、DeepSpeed、TorchTitan 重叠在「能 3D 并行训 Transformer」。差异化曾经是高维 TP + Gemini；2026 年读代码应以插件矩阵为准，而不是以 2021 摘要为准。</p><p><span class="marginnote">出处：Bian 等 arXiv:2110.14883；2D/2.5D/3D 张量并行的分篇论文（Xu、Wang、Bian）；PatrickStar arXiv:2108.05818；Colossal-AI 文档 <em>Meet Gemini</em> 与 Booster plugins。禁止给未标注出处的「单卡 GPT-3」演示填造 FLOPS。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Colossal-AI 是统一并行训练系统：多维 TP、PP、ZeRO 式分片，外加 Gemini 动态异构内存。</li><li>2D/2.5D/3D 切分写在 2021 论文；当前主线以 GeminiPlugin / ShardFormer 为入口，旧 TP 模块可能需示例仓。</li><li>Gemini 相对静态 Offload：warmup 采样 + 按迭代搬张量。</li><li>出处：arXiv:2110.14883；开源 hpcaitech/ColossalAI。</li></ul>',14))])}const C=i(c,[["render",h]]);export{S as __pageData,C as default};
